<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panacea Restaurant — Operations Studio</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root{--bg:#f8f7f2;--paper:#fff;--ink:#183a30;--muted:#79887f;--line:#e7e9e1;--orange:#d77a48;--green:#214a3b;--soft:#edf3eb;--shadow:0 16px 42px #1b3b2b0c;font-family:'DM Sans',system-ui,sans-serif;color:var(--ink);background:var(--bg)}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #d8a475;outline-offset:2px}button:disabled{opacity:.4;cursor:not-allowed}a{color:inherit;text-decoration:none}.app{display:grid;grid-template-columns:244px minmax(0,1fr);min-height:100vh}.sidebar{background:#173d32;color:#eaf0e9;padding:27px 17px;display:flex;flex-direction:column;gap:34px;position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:10px;padding:0 11px}.brand-icon{background:#dba477;color:#173d32;width:40px;height:40px;display:grid;place-items:center;border-radius:13px;font-size:26px}.brand b{font:800 21px Manrope;letter-spacing:-1.1px}.brand small{display:block;font-size:9px;letter-spacing:2.1px;color:#afc6b8}.nav-label{font-size:10px;color:#9fb8a7;letter-spacing:2px;margin:0 13px 14px}.nav{display:grid;gap:5px}.nav button{border:0;border-radius:12px;padding:13px 15px;background:transparent;color:#b9d0c2;display:flex;align-items:center;gap:13px;text-align:left;width:100%;font-weight:600}.nav button:hover{background:#2b5847}.nav button.active{background:#eff4e9;color:#1b4033}.nav .glyph{font-size:19px;width:23px;text-align:center}.side-note{margin-top:auto;border:1px solid #426858;padding:17px;border-radius:16px;color:#bad0c2;font-size:12px;line-height:1.7}.side-note strong{display:block;color:white}.content{padding:29px clamp(18px,3.7vw,65px) 45px;max-width:1680px;width:100%;margin:auto;min-width:0}.topbar{display:flex;justify-content:space-between;align-items:center;gap:15px;padding-bottom:23px;border-bottom:1px solid var(--line)}.crumb{font-size:11px;letter-spacing:1.7px;color:var(--muted);font-weight:800}.top-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.status{background:#e5f2e6;color:#397650;padding:8px 12px;border-radius:99px;font-size:11px;font-weight:800}.mode-btn{border:1px solid var(--line);background:var(--paper);padding:10px 14px;border-radius:10px;color:var(--ink);font-size:12px;font-weight:800}.mode-btn.selected{background:#dceee0;border-color:#8ec1a2}.avatar{background:#e8c7ac;border-radius:50%;height:38px;width:38px;display:grid;place-items:center;font-weight:800}.page{display:none;animation:rise .35s ease both}.page.active{display:block}@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}.heading{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:32px 0 24px}.eyebrow{font-size:11px;letter-spacing:2px;color:var(--orange);font-weight:800;text-transform:uppercase}h1,h2,h3{font-family:Manrope,sans-serif;letter-spacing:-.9px}h1{font-size:clamp(28px,3vw,42px);line-height:1.2;margin:8px 0 9px}h2{font-size:20px;margin:0}h3{font-size:15px;margin:0}p{color:var(--muted);line-height:1.6;margin:6px 0}.btn{border:0;background:var(--green);color:#fff;padding:12px 17px;border-radius:11px;font-weight:800;font-size:12px;display:inline-flex;align-items:center;justify-content:center;gap:8px}.btn.alt{background:#e9f0e6;color:#23503c}.btn.terra{background:var(--orange)}.hero{border-radius:22px;min-height:270px;position:relative;overflow:hidden;background:linear-gradient(90deg,#183d32 0%,#183d32e8 39%,#183d3244 100%),url('https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=1400&q=85') center/cover;color:white;padding:38px 40px;display:flex;align-items:center;box-shadow:var(--shadow)}.hero:after{content:'✦';position:absolute;right:30%;top:18%;font-size:90px;color:#ffffff15;animation:float 5s ease-in-out infinite}@keyframes float{50%{transform:translateY(-13px) rotate(12deg)}}.hero-content{position:relative;z-index:1;max-width:530px}.hero .eyebrow{color:#efb989}.hero h1{font-size:clamp(29px,3.4vw,48px);line-height:1.16}.hero p{color:#d8e6d9;max-width:420px}.hero .btn{margin-top:16px;background:#f2e9d8;color:#244435}.hero-tag{position:absolute;right:22px;bottom:22px;background:#ffffffdc;color:#1c4636;border-radius:12px;padding:12px 16px;font-size:12px;font-weight:800;backdrop-filter:blur(12px)}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:22px 0}.stat,.panel,.food-card,.ticket,.reservation-card{background:var(--paper);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}.stat{padding:21px;transition:transform .2s}.stat:hover,.food-card:hover{transform:translateY(-4px)}.stat small{font-size:12px;color:var(--muted)}.stat strong{display:block;font:800 33px Manrope;margin:10px 0 5px;letter-spacing:-1px}.stat .spark{font-size:12px;color:#4c9771}.cols{display:grid;grid-template-columns:1.35fr 1fr;gap:18px}.panel{padding:23px;min-width:0}.panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:20px}.muted{font-size:12px;color:var(--muted)}.chart{height:180px;display:flex;align-items:end;gap:12px;border-bottom:1px solid var(--line);padding:10px 4px 0}.chart-col{flex:1;display:flex;align-items:center;flex-direction:column;justify-content:end;height:100%;gap:7px}.chart-bar{width:100%;max-width:48px;border-radius:9px 9px 3px 3px;background:linear-gradient(180deg,#e2a779,#d77a48);min-height:4px;animation:grow .75s ease both;transform-origin:bottom}.chart-col:nth-child(even) .chart-bar{background:linear-gradient(180deg,#a9cdb4,#39775c)}@keyframes grow{from{transform:scaleY(.06)}}.chart-col span{font-size:10px;color:var(--muted)}.feed{display:grid;gap:12px}.feed-row{display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid var(--line);padding:0 0 13px}.feed-row:last-child{border:0}.feed-row b{font-size:13px}.feed-row small{display:block;color:var(--muted);margin-top:4px}.pill{display:inline-flex;border-radius:8px;padding:7px 9px;font-size:10px;font-weight:800;background:#f8e9da;color:#a86838;white-space:nowrap}.pill.preparing{background:#fcebd4;color:#aa722e}.pill.ready{background:#dff0e4;color:#397a51}.pill.delivered{background:#e9ece8;color:#63756b}.section-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 19px;flex-wrap:wrap}.search{padding:11px 14px;border:1px solid var(--line);background:var(--paper);border-radius:11px;color:var(--ink);min-width:210px}.filters{display:flex;gap:8px;flex-wrap:wrap}.filter{background:var(--paper);border:1px solid var(--line);color:var(--muted);padding:9px 13px;border-radius:9px;font-size:12px;font-weight:700}.filter.active{background:var(--green);color:#fff}.tickets{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.ticket{padding:19px;animation:rise .3s ease both}.ticket-top{display:flex;justify-content:space-between;align-items:start;gap:10px}.ticket h3{font-size:18px}.ticket .items{border-top:1px dashed var(--line);border-bottom:1px dashed var(--line);margin:17px 0;padding:13px 0;font-size:12px;color:var(--muted);line-height:1.9;min-height:70px}.ticket-bottom{display:flex;justify-content:space-between;align-items:center;gap:10px}.ticket-bottom strong{font-size:17px}.ticket .btn{padding:9px 11px}.food-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.food-card{overflow:hidden;transition:transform .2s}.food-img{width:100%;aspect-ratio:1.35;object-fit:cover;background:#e9ede4;display:block}.food-info{padding:16px}.food-info b{font-size:14px}.food-info p{font-size:11px;margin:7px 0 14px}.food-foot{display:flex;align-items:center;justify-content:space-between;gap:10px}.food-foot strong{font-size:16px}.food-foot button{background:#e7efe7;color:#1f563e;border:0;border-radius:9px;padding:8px 12px;font-weight:800}.reservation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.reservation-card{padding:18px}.reservation-card .time{font:800 26px Manrope;color:var(--orange)}.reservation-card .details{margin-top:12px;font-size:12px;color:var(--muted)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;text-align:left}td,th{padding:14px;border-bottom:1px solid var(--line);font-size:12px}th{color:var(--muted);text-transform:uppercase;font-size:10px;letter-spacing:1px}.empty{padding:34px 15px;border:1px dashed var(--line);border-radius:13px;text-align:center;color:var(--muted);font-size:13px}.notice{margin-top:22px;border:1px solid var(--line);border-radius:12px;padding:14px 18px;color:var(--muted);font-size:12px;line-height:1.6;background:var(--paper)}.toast{position:fixed;right:25px;bottom:25px;background:#214a3b;color:white;border-radius:12px;padding:15px 20px;box-shadow:0 12px 30px #0003;z-index:10;animation:rise .25s ease}.hidden{display:none!important}.dark{--bg:#10251e;--paper:#1b362b;--ink:#eaf2e9;--muted:#a6b9aa;--line:#365044;--green:#dba477;--soft:#294638;--shadow:none}.dark .btn{color:#193c30}.dark .mode-btn.selected{background:#3c644d;color:white}.dark .pill.delivered{background:#365044;color:#c8d6cc}.dark .food-foot button{background:#315740;color:white}.dark .hero .btn{color:#173d32}
@media(max-width:1200px){.food-grid{grid-template-columns:repeat(2,1fr)}.tickets{grid-template-columns:repeat(2,1fr)}}@media(max-width:980px){.app{grid-template-columns:72px 1fr}.sidebar{padding:20px 8px}.brand{justify-content:center;padding:0}.brand b,.brand small,.nav-label,.nav button .nav-text,.side-note{display:none}.nav button{justify-content:center;padding:12px 7px}.cols{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:660px){.app{display:block}.sidebar{position:static;height:auto;flex-direction:row;align-items:center;gap:8px;padding:10px;overflow:auto}.nav{display:flex}.nav button{min-width:43px}.content{padding:18px 13px}.topbar{align-items:start;gap:8px}.top-actions{justify-content:end}.crumb{font-size:9px}.status{display:none}.hero{padding:26px;min-height:270px}.hero-tag{display:none}.heading{align-items:start;flex-direction:column}.stats{gap:9px}.stat{padding:14px}.stat strong{font-size:25px}.tickets,.reservation-grid,.food-grid{grid-template-columns:1fr 1fr}.food-info{padding:12px}}@media(max-width:440px){.tickets,.reservation-grid{grid-template-columns:1fr}.food-grid{gap:9px}.food-img{aspect-ratio:1}.food-info p{display:none}.food-foot{margin-top:12px}.hero h1{font-size:28px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}

.room-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(270px,.75fr);gap:18px}.floor{background:#e6e9dc;border:1px solid #d2d9cb;border-radius:23px;padding:23px;min-height:510px;background-image:radial-gradient(#a4b5a321 1px,transparent 1px);background-size:18px 18px}.floor-top,.floor-legend{display:flex;justify-content:space-between;gap:10px;color:#698170;font-size:11px;letter-spacing:1px}.floor-legend{justify-content:start;flex-wrap:wrap;margin-top:25px;letter-spacing:0}.room-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin:45px 5px}.table-unit{border:2px solid #bdd0bd;border-radius:50%;aspect-ratio:1;min-width:0;background:#f7faf4;color:#24563d;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;box-shadow:0 8px 0 #c6d3c4;transition:transform .2s,box-shadow .2s}.table-unit:hover{transform:translateY(-5px);box-shadow:0 13px 0 #c6d3c4}.table-unit.occupied{background:#f9ead7;border-color:#e5bb8a;color:#8d5b28}.table-unit.kitchen{background:#dce9f9;border-color:#9bb9df;color:#3c6397}.table-unit.bill{background:#f6dce1;border-color:#dfa0aa;color:#a04459}.table-unit strong{font:800 19px Manrope}.table-unit small{font-size:10px}.detail-line{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:13px 0;border-bottom:1px solid var(--line);font-size:13px}.detail-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:20px}.field{display:grid;gap:8px;margin:18px 0}.field label{font-size:12px;font-weight:800;color:var(--muted)}.field input,.field select{width:100%;background:var(--paper);border:1px solid var(--line);color:var(--ink);padding:12px;border-radius:10px}.profile-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px}.profile{padding:22px;background:var(--paper);border:1px solid var(--line);border-radius:18px}.profile .face{height:54px;width:54px;border-radius:50%;display:grid;place-items:center;background:#ead7c1;font-size:25px;margin-bottom:15px}.profile strong{display:block;font:800 17px Manrope}.profile p{font-size:12px}.drawer-backdrop{position:fixed;inset:0;background:#0b2419a3;z-index:30;backdrop-filter:blur(3px)}.drawer{position:fixed;right:0;top:0;bottom:0;width:min(470px,100vw);background:var(--paper);z-index:31;padding:25px;overflow:auto;box-shadow:-20px 0 60px #0002;animation:drawerIn .25s ease}@keyframes drawerIn{from{transform:translateX(100%)}}.drawer>button{margin-bottom:25px}.alert-row{border-left:3px solid #d77a48;padding:16px;margin:12px 0;background:var(--soft);border-radius:0 10px 10px 0}.dark .floor{background-color:#294638;border-color:#3c5b47}.dark .table-unit{box-shadow:0 8px 0 #17362a}.dark .table-unit:hover{box-shadow:0 13px 0 #17362a}.dark .table-unit:not(.occupied):not(.kitchen):not(.bill){background:#315c44;color:#e7f0e9}@media(max-width:1080px){.room-layout{grid-template-columns:1fr}.profile-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.room-grid{grid-template-columns:repeat(3,1fr);gap:12px}.floor{padding:12px;min-height:auto}.profile-grid{grid-template-columns:1fr}}</style></head><body>
<div class="app"><aside class="sidebar"><div class="brand"><span class="brand-icon">✳</span><div><b>panacea</b><small>RESTAURANT</small></div></div><div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Módulos"><button class="active" data-page="inicio"><span class="glyph">◈</span><span class="nav-text">Inicio</span></button><button data-page="pedidos"><span class="glyph">▤</span><span class="nav-text">Pedidos</span></button><button data-page="cocina"><span class="glyph">◫</span><span class="nav-text">Cocina</span></button><button data-page="reservas"><span class="glyph">▦</span><span class="nav-text">Reservas</span></button><button data-page="menu"><span class="glyph">▧</span><span class="nav-text">Menú</span></button><button data-page="salon"><span class="glyph">▦</span><span class="nav-text">Salón y mesas</span></button><button data-page="caja"><span class="glyph">▣</span><span class="nav-text">Caja y cobros</span></button><button data-page="inventario"><span class="glyph">◩</span><span class="nav-text">Inventario</span></button><button data-page="clientes"><span class="glyph">♙</span><span class="nav-text">Clientes</span></button><button data-page="personal"><span class="glyph">♧</span><span class="nav-text">Personal</span></button><button data-page="incidencias"><span class="glyph">⚑</span><span class="nav-text">Incidencias</span></button><button data-page="simulador"><span class="glyph">◇</span><span class="nav-text">Simulador</span></button><button data-page="gerencia"><span class="glyph">▥</span><span class="nav-text">Gerencia</span></button></nav></div><div class="side-note"><strong>Operations Studio</strong>Panacea Logic AI<br>Demostración y datos reales</div></aside>
<main class="content"><header class="topbar"><span class="crumb">PANACEA / RESTAURANT / STUDIO</span><div class="top-actions"><span class="status" id="dataStatus">● DATOS REALES</span><button class="mode-btn" id="demoToggle" type="button">✦ Activar demo</button><button class="mode-btn" id="themeToggle" type="button" aria-label="Cambiar tema">◐</button><span class="avatar">P</span></div></header>
<section class="page active" id="inicio"><div class="heading"><div><div class="eyebrow">TU CENTRO DE OPERACIONES</div><h1>Hola, qué gusto verte.</h1><p>Tu restaurante, sus números y todo lo que sucede ahora.</p></div><a class="btn" href="/panacea-operations">Administración ↗</a></div>
<div class="hero"><div class="hero-content"><div class="eyebrow">EL ARTE DE OPERAR MEJOR</div><h1>Más tiempo para lo que importa.</h1><p>Desde el primer pedido hasta el último servicio. Una operación fluida, conectada y hecha para tu equipo.</p><button class="btn" data-jump="pedidos">Explorar pedidos →</button></div><div class="hero-tag">✳ Diseñado para restaurantes reales</div></div>
<div class="stats" id="homeStats"></div><div class="cols"><div class="panel"><div class="panel-head"><h2>Ritmo del restaurante</h2><span class="muted" id="chartCaption">Volumen de pedidos</span></div><div class="chart" id="salesChart"></div></div><div class="panel"><div class="panel-head"><h2>Actividad reciente</h2><button class="btn alt" data-jump="pedidos">Ver pedidos ↗</button></div><div class="feed" id="activityFeed"></div></div></div></section>
<section class="page" id="pedidos"><div class="heading"><div><div class="eyebrow">CONTROL EN TIEMPO REAL</div><h1>Pedidos, sin complicaciones.</h1><p>Del mostrador a la cocina, cada pedido en su lugar.</p></div><button class="btn terra" id="addOrder">+ Pedido de ejemplo</button></div><div class="section-toolbar"><div class="filters" id="orderFilters"><button class="filter active" data-filter="all">Todos</button><button class="filter" data-filter="pending">Pendientes</button><button class="filter" data-filter="preparing">En preparación</button><button class="filter" data-filter="ready">Listos</button><button class="filter" data-filter="delivered">Entregados</button></div><input class="search" id="orderSearch" placeholder="Buscar mesa o pedido..." aria-label="Buscar pedidos"></div><div class="tickets" id="orderTickets"></div></section>
<section class="page" id="cocina"><div class="heading"><div><div class="eyebrow">KITCHEN DISPLAY</div><h1>La cocina tiene el control.</h1><p>Visualiza las comandas y avanza su preparación con un toque.</p></div><button class="btn alt" data-jump="pedidos">Ver todos los pedidos ↗</button></div><div class="tickets" id="kitchenTickets"></div></section>
<section class="page" id="reservas"><div class="heading"><div><div class="eyebrow">HOSPITALIDAD EN CADA DETALLE</div><h1>Cada mesa, una experiencia.</h1><p>Consulta las reservas y organiza la atención.</p></div><button class="btn terra" id="addReservation">+ Reserva de ejemplo</button></div><div class="reservation-grid" id="reservationCards"></div></section>
<section class="page" id="menu"><div class="heading"><div><div class="eyebrow">EL CORAZÓN DE TU RESTAURANTE</div><h1>Un menú que se antoja.</h1><p>Productos presentados con claridad, imágenes y precios.</p></div><button class="btn alt" data-jump="pedidos">Ir a pedidos ↗</button></div><div class="section-toolbar"><div class="filters" id="menuFilters"><button class="filter active" data-category="all">Todo</button><button class="filter" data-category="Principales">Principales</button><button class="filter" data-category="Entradas">Entradas</button><button class="filter" data-category="Bebidas">Bebidas</button></div><input class="search" id="menuSearch" placeholder="Buscar producto..." aria-label="Buscar producto"></div><div class="food-grid" id="foodGrid"></div></section>
<section class="page" id="gerencia"><div class="heading"><div><div class="eyebrow">VISIÓN DE NEGOCIO</div><h1>Decisiones con perspectiva.</h1><p>Indicadores del restaurante, claramente identificados por origen.</p></div><a class="btn" href="/panacea-operations">Panel original ↗</a></div><div class="stats" id="managerStats"></div><div class="cols"><div class="panel"><div class="panel-head"><h2>Distribución de pedidos</h2><span class="muted" id="managerCaption">Por estado</span></div><div id="managerBreakdown"></div></div><div class="panel"><div class="panel-head"><h2>Estado del catálogo</h2></div><div id="managerCatalog"></div></div></div></section>

<section class="page" id="salon"><div class="heading"><div><div class="eyebrow">SALÓN / SERVICIO EN VIVO</div><h1>El restaurante, de un vistazo.</h1><p>Selecciona una mesa para abrir su ficha, tomar pedidos y preparar su cuenta.</p></div><button class="btn" id="resetTables">↻ Reiniciar salón</button></div><div class="room-layout"><div class="floor"><div class="floor-top"><b>✳ SALÓN PRINCIPAL</b><span>ENTRADA →</span></div><div class="room-grid" id="roomGrid"></div><div class="floor-legend"><span>● Disponible</span><span>● Ocupada</span><span>● En cocina</span><span>● Cuenta pendiente</span></div></div><div class="panel" id="tableDetail"><h2>Selecciona una mesa</h2><p>Abre su ficha para conocer los pedidos y acciones disponibles.</p></div></div></section>
<section class="page" id="caja"><div class="heading"><div><div class="eyebrow">PUNTO DE VENTA</div><h1>Cobros sin fricción.</h1><p>Cuentas por mesa, división entre personas, descuentos y propinas.</p></div></div><div class="cols"><div class="panel"><div class="panel-head"><h2>Cuentas abiertas</h2><span class="muted">Simulación comercial</span></div><div id="openBills"></div></div><div class="panel"><div class="panel-head"><h2>Terminal de cobro</h2><span class="pill">Caja 01</span></div><div id="checkoutPanel"></div></div></div></section>
<section class="page" id="inventario"><div class="heading"><div><div class="eyebrow">CONTROL DE INSUMOS</div><h1>Cada ingrediente cuenta.</h1><p>Existencias, costos, recetas, alertas y sugerencias de reposición.</p></div><button class="btn" id="restockAll">+ Generar propuesta de compra</button></div><div class="stats" id="stockStats"></div><div class="panel"><div class="panel-head"><h2>Ingredientes y disponibilidad</h2><span class="muted">Stock de demostración</span></div><div class="table-wrap" id="stockTable"></div></div><div class="panel" style="margin-top:18px" id="purchaseProposal"></div></section>
<section class="page" id="clientes"><div class="heading"><div><div class="eyebrow">RELACIÓN CON EL CLIENTE</div><h1>Hospitalidad que se recuerda.</h1><p>Historial de visitas, preferencias consentidas y recompensas.</p></div></div><div class="profile-grid" id="customerProfiles"></div></section>
<section class="page" id="personal"><div class="heading"><div><div class="eyebrow">EQUIPO / TURNOS</div><h1>Un equipo coordinado.</h1><p>Roles, turnos y tareas operativas de cada estación.</p></div></div><div class="profile-grid" id="staffProfiles"></div></section>
<section class="page" id="incidencias"><div class="heading"><div><div class="eyebrow">CENTRO DE ATENCIÓN</div><h1>Lo urgente, bajo control.</h1><p>Identifica incidencias, asigna responsables y registra su resolución.</p></div><button class="btn terra" id="newIncident">+ Registrar incidencia</button></div><div class="panel" id="incidentList"></div></section>
<section class="page" id="simulador"><div class="heading"><div><div class="eyebrow">LABORATORIO DE DECISIONES</div><h1>Explora antes de decidir.</h1><p>Simula cambios en precio, costo y demanda. Resultados ilustrativos, no predicciones.</p></div></div><div class="cols"><div class="panel"><h2>Escenario comercial</h2><div class="field"><label for="simPrice">Precio del plato ($)</label><input id="simPrice" type="number" min="0" step=".5" value="16.5"></div><div class="field"><label for="simCost">Costo por plato ($)</label><input id="simCost" type="number" min="0" step=".5" value="6.8"></div><div class="field"><label for="simVolume">Unidades por semana</label><input id="simVolume" type="number" min="0" step="1" value="120"></div><div class="field"><label for="simDiscount">Descuento promocional (%)</label><input id="simDiscount" type="range" min="0" max="35" step="1" value="0"><span id="discountLabel">0%</span></div></div><div class="panel"><h2>Resultado del escenario</h2><div id="simResults"></div></div></div></section>
<div class="drawer-backdrop hidden" id="drawerBackdrop"></div><aside class="drawer hidden" id="drawer" aria-label="Detalles" role="dialog" aria-modal="true"><button class="mode-btn" id="closeDrawer">✕ Cerrar</button><div id="drawerContent"></div></aside><div class="notice" id="disclaimer"><strong>Datos reales:</strong> consultas de solo lectura sobre la base de datos local. Las acciones de creación y avance de pedidos están disponibles únicamente en el modo demostración; no escriben en MariaDB. Las imágenes del modo demo son ilustrativas.</div></main></div><div class="toast hidden" id="toast" role="status" aria-live="polite"></div>
<script>
const real=@json($panaceaData);
const photos=[
'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?w=650&q=80',
'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=650&q=80',
'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=650&q=80',
'https://images.unsplash.com/photo-1547592180-85f173990554?w=650&q=80',
'https://images.unsplash.com/photo-1552566626-52f8b828add9?w=650&q=80',
'https://images.unsplash.com/photo-1513558161293-cdaf765edfd7?w=650&q=80',
'https://images.unsplash.com/photo-1551024709-8f23befc6f87?w=650&q=80',
'https://images.unsplash.com/photo-1559847844-5315695dadae?w=650&q=80'];
const demoProducts=[
{id:1,name:'Pizza artesanal',category:'Principales',price:16.5,description:'Masa fermentada, tomate y albahaca fresca',image:photos[0]},
{id:2,name:'Bowl mediterráneo',category:'Principales',price:13.5,description:'Vegetales frescos, granos y aderezo de la casa',image:photos[1]},
{id:3,name:'Hamburguesa de la casa',category:'Principales',price:15,description:'Carne a la parrilla y pan brioche',image:photos[2]},
{id:4,name:'Ensalada de temporada',category:'Entradas',price:10,description:'Ingredientes de estación y vinagreta',image:photos[3]},
{id:5,name:'Entrada para compartir',category:'Entradas',price:12,description:'Selección del chef para comenzar',image:photos[4]},
{id:6,name:'Cóctel cítrico',category:'Bebidas',price:7,description:'Fruta fresca, hielo y notas cítricas',image:photos[5]},
{id:7,name:'Limonada especial',category:'Bebidas',price:5.5,description:'Preparada al momento',image:photos[6]},
{id:8,name:'Especial del chef',category:'Principales',price:19,description:'Nuestra recomendación de temporada',image:photos[7]}];
const initialOrders=[
{id:1048,table:'Mesa 04',items:['2 × Pizza artesanal','1 × Limonada especial'],total:38.5,status:'pending',time:'12:42'},
{id:1047,table:'Mesa 08',items:['1 × Hamburguesa de la casa','1 × Cóctel cítrico'],total:22,status:'preparing',time:'12:35'},
{id:1046,table:'Para llevar',items:['2 × Bowl mediterráneo'],total:27,status:'ready',time:'12:24'},
{id:1045,table:'Mesa 02',items:['1 × Especial del chef','1 × Ensalada de temporada'],total:29,status:'delivered',time:'12:12'},
{id:1044,table:'Mesa 06',items:['1 × Pizza artesanal'],total:16.5,status:'preparing',time:'12:06'}];
const initialReservations=[{id:1,time:'13:00',name:'Familia Rodríguez',party:4,table:'Mesa 05',state:'Confirmada'},{id:2,time:'14:30',name:'María González',party:2,table:'Mesa 02',state:'Confirmada'},{id:3,time:'19:00',name:'Grupo empresarial',party:6,table:'Mesa 10',state:'Pendiente'},{id:4,time:'20:15',name:'Carlos Pérez',party:3,table:'Mesa 07',state:'Confirmada'}];
let demo=false,orders=[],reservations=[],filter='all',category='all',nextId=1049;
const safe=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const money=n=>'$'+Number(n||0).toFixed(2);
const labels={pending:'Pendiente',preparing:'En preparación',ready:'Listo',delivered:'Entregado'};
const next={pending:'preparing',preparing:'ready',ready:'delivered'};
function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(window.panaceaToastTimer);window.panaceaToastTimer=setTimeout(()=>el.classList.add('hidden'),2700)}
function realOrders(){return (real.orders.rows||[]).map(r=>({id:r.order_id??'—',table:r.order_type??'Pedido',items:['Pedido registrado en la base de datos'],total:Number(r.order_total??r.total??0),status:'unknown',time:String(r.created_at??'').slice(11,16),rawStatus:r.status_id}))}
function realProducts(){return (real.menus.rows||[]).map((r,i)=>({id:r.menu_id??i,name:r.menu_name??'Producto '+(i+1),category:'Catálogo',price:Number(r.menu_price??r.price??0),description:'Producto del catálogo real',image:photos[i%photos.length]}))}
function realReservations(){return (real.reservations.rows||[]).map((r,i)=>({id:r.reservation_id??i,time:String(r.reserve_time??'—').slice(0,5),name:'Reserva #'+(r.reservation_id??i),party:null,table:'Fecha: '+(r.reserve_date??'—'),state:'Estado '+(r.status_id??'—')}))}
const getOrders=()=>demo?orders:realOrders(),getProducts=()=>demo?demoProducts:realProducts(),getReservations=()=>demo?reservations:realReservations();
function metric(label,value,caption){return '<article class="stat"><small>'+safe(label)+'</small><strong>'+safe(value)+'</strong><span class="spark">'+safe(caption)+'</span></article>'}
function noData(text){return '<div class="empty">'+safe(text)+'</div>'}
function show(page){document.querySelectorAll('.page').forEach(e=>e.classList.toggle('active',e.id===page));document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===page));history.replaceState(null,'','#'+page);window.scrollTo({top:0,behavior:'smooth'})}
function renderHome(){const o=getOrders(),p=getProducts(),r=getReservations();document.getElementById('homeStats').innerHTML=metric('Pedidos registrados',demo?o.length:real.orders.count,demo?'Escenario ficticio':'Base de datos')+metric('Productos',demo?p.length:real.menus.count,'En el catálogo')+metric('Reservas',demo?r.length:real.reservations.count,'Registradas')+metric('Pedidos en proceso',demo?o.filter(x=>['pending','preparing'].includes(x.status)).length:'—',demo?'En espera o cocina':'Requiere mapear estados');const counts=demo?[4,6,3,8,7,9,5]:[0,0,0,0,0,0,0];document.getElementById('chartCaption').textContent=demo?'Actividad simulada · 7 franjas':'Sin serie horaria validada';document.getElementById('salesChart').innerHTML=demo?counts.map((n,i)=>'<div class="chart-col"><div class="chart-bar" style="height:'+(n*10)+'%"></div><span>'+['10h','11h','12h','13h','14h','15h','16h'][i]+'</span></div>').join(''):noData('El gráfico se habilitará al validar fechas y estados de los pedidos reales.');document.getElementById('activityFeed').innerHTML=o.length?o.slice(0,4).map(x=>'<div class="feed-row"><div><b>#'+safe(x.id)+' · '+safe(x.table)+'</b><small>'+safe(x.time||'Registro')+'</small></div><span class="pill '+safe(x.status)+'">'+safe(labels[x.status]??('Estado '+(x.rawStatus??'—')))+'</span></div>').join(''):noData('Aún no hay pedidos registrados. Activa el modo demo para explorar.')}
function renderOrders(){const query=document.getElementById('orderSearch').value.toLowerCase();const list=getOrders().filter(x=>(filter==='all'||x.status===filter)&&(String(x.id)+' '+x.table+' '+x.items.join(' ')).toLowerCase().includes(query));document.getElementById('orderTickets').innerHTML=list.length?list.map(x=>'<article class="ticket"><div class="ticket-top"><div><span class="eyebrow">PEDIDO #'+safe(x.id)+'</span><h3>'+safe(x.table)+'</h3><p class="muted">'+safe(x.time||'Registrado')+'</p></div><span class="pill '+safe(x.status)+'">'+safe(labels[x.status]??('Estado '+(x.rawStatus??'—')))+'</span></div><div class="items">'+x.items.map(safe).join('<br>')+'</div><div class="ticket-bottom"><strong>'+money(x.total)+'</strong>'+(demo&&next[x.status]?'<button class="btn" data-advance="'+safe(x.id)+'">'+safe(x.status==='pending'?'Enviar a cocina':x.status==='preparing'?'Marcar listo':'Entregar')+' →</button>':'<span class="muted">'+(demo?'Completado':'Solo lectura')+'</span>')+'</div></article>').join(''):noData('No hay pedidos para esta vista. '+(demo?'Crea uno con el botón superior.':'Activa la demostración para ver el flujo.'))}
function renderKitchen(){const list=getOrders().filter(x=>demo?['pending','preparing','ready'].includes(x.status):true);document.getElementById('kitchenTickets').innerHTML=list.length?list.map(x=>'<article class="ticket"><div class="ticket-top"><div><span class="eyebrow">COMANDA #'+safe(x.id)+'</span><h3>'+safe(x.table)+'</h3></div><span class="pill '+safe(x.status)+'">'+safe(labels[x.status]??'Registrado')+'</span></div><div class="items">'+x.items.map(safe).join('<br>')+'</div><div class="ticket-bottom"><span class="muted">'+safe(x.time||'')+'</span>'+(demo&&next[x.status]?'<button class="btn" data-advance="'+safe(x.id)+'">'+safe(x.status==='pending'?'Comenzar':x.status==='preparing'?'Terminar':'Entregar')+' →</button>':'<span class="muted">'+(demo?'Completado':'Solo lectura')+'</span>')+'</div></article>').join(''):noData('No hay comandas pendientes.')}
function renderReservations(){const r=getReservations();document.getElementById('reservationCards').innerHTML=r.length?r.map(x=>'<article class="reservation-card"><div class="eyebrow">RESERVA #'+safe(x.id)+'</div><div class="time">'+safe(x.time)+'</div><h3>'+safe(x.name)+'</h3><div class="details">'+(x.party?safe(x.party)+' personas · ':'')+safe(x.table)+'</div><div style="margin-top:17px"><span class="pill ready">'+safe(x.state)+'</span></div></article>').join(''):noData('Todavía no hay reservas. Activa la demostración para explorar.')}
function renderMenu(){const query=document.getElementById('menuSearch').value.toLowerCase();const p=getProducts().filter(x=>(category==='all'||x.category===category)&&(x.name+' '+x.description).toLowerCase().includes(query));document.getElementById('foodGrid').innerHTML=p.length?p.map(x=>'<article class="food-card"><img class="food-img" src="'+safe(x.image)+'" alt="Imagen ilustrativa de '+safe(x.name)+'" loading="lazy" onerror="this.style.display=\'none\'"><div class="food-info"><span class="eyebrow">'+safe(x.category)+'</span><div style="margin-top:8px"><b>'+safe(x.name)+'</b></div><p>'+safe(x.description)+'</p><div class="food-foot"><strong>'+money(x.price)+'</strong><button data-product="'+safe(x.id)+'" '+(!demo?'disabled title="Disponible solo en demo"':'')+'>+ Pedido</button></div></div></article>').join(''):noData('No se encontraron productos. '+(demo?'Prueba otra categoría.':'Activa la demo para ver un catálogo ilustrado.'))}
function renderManager(){const o=getOrders(),p=getProducts(),r=getReservations();document.getElementById('managerStats').innerHTML=metric('Pedidos',demo?o.length:real.orders.count,'Total registrado')+metric('Productos',demo?p.length:real.menus.count,'Catálogo')+metric('Reservas',demo?r.length:real.reservations.count,'Total')+metric('Ingresos',demo?money(o.filter(x=>x.status==='delivered').reduce((s,x)=>s+x.total,0)):'—',demo?'Ejemplo · entregados':'Sin validación contable');document.getElementById('managerCaption').textContent=demo?'Datos de demostración':'Estados reales no mapeados';document.getElementById('managerBreakdown').innerHTML=demo?Object.keys(labels).map(k=>{const count=o.filter(x=>x.status===k).length;return '<div style="margin:15px 0"><div class="feed-row"><b>'+safe(labels[k])+'</b><span>'+count+'</span></div><div style="height:8px;border-radius:8px;background:var(--soft);overflow:hidden"><div style="height:100%;width:'+(o.length?count/o.length*100:0)+'%;background:var(--orange);border-radius:8px"></div></div></div>'}).join(''):noData('Para reportes por estado debemos validar la tabla de estados de TastyIgniter.');document.getElementById('managerCatalog').innerHTML='<div class="feed-row"><b>Productos</b><strong>'+p.length+'</strong></div><div class="feed-row"><b>Reservas</b><strong>'+r.length+'</strong></div><div class="feed-row"><b>Origen</b><span class="pill">'+(demo?'Simulación':'MariaDB')+'</span></div>'}
function render(){document.getElementById('dataStatus').textContent=demo?'✦ DEMOSTRACIÓN':'● DATOS REALES';document.getElementById('demoToggle').textContent=demo?'↩ Ver datos reales':'✦ Activar demo';document.getElementById('demoToggle').classList.toggle('selected',demo);document.getElementById('addOrder').disabled=!demo;document.getElementById('addReservation').disabled=!demo;document.getElementById('disclaimer').innerHTML=demo?'<strong>Modo demostración:</strong> restaurante ficticio con ejemplos interactivos. Los pedidos, reservas, importes y gráficos son simulados; ninguna acción escribe en MariaDB. Las fotografías son ilustrativas.':'<strong>Datos reales:</strong> consultas de solo lectura de la base de datos local. Los estados y cifras financieras requieren validación adicional; no se simulan. Activa la demo para probar interacciones.';renderHome();renderOrders();renderKitchen();renderReservations();renderMenu();renderManager()}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.page)));document.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.jump)));document.getElementById('demoToggle').addEventListener('click',()=>{demo=!demo;if(demo){orders=structuredClone(initialOrders);reservations=structuredClone(initialReservations);nextId=1049;filter='all';category='all';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category==='all'))}render();notify(demo?'Demostración activada · datos ficticios':'Vista de datos reales activada')});document.getElementById('themeToggle').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));
document.getElementById('orderFilters').addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderOrders()});document.getElementById('menuFilters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));renderMenu()});document.getElementById('orderSearch').addEventListener('input',renderOrders);document.getElementById('menuSearch').addEventListener('input',renderMenu);
document.addEventListener('click',e=>{const advance=e.target.closest('[data-advance]');if(advance&&demo){const o=orders.find(x=>String(x.id)===advance.dataset.advance);if(o&&next[o.status]){o.status=next[o.status];render();notify('Pedido #'+o.id+' → '+labels[o.status])}}const product=e.target.closest('[data-product]');if(product&&demo){const p=demoProducts.find(x=>String(x.id)===product.dataset.product);if(p){orders.unshift({id:nextId++,table:'Mostrador',items:['1 × '+p.name],total:p.price,status:'pending',time:new Date().toLocaleTimeString('es-PA',{hour:'2-digit',minute:'2-digit'})});render();show('pedidos');notify('Pedido de demostración creado')}}});
document.getElementById('addOrder').addEventListener('click',()=>{if(!demo)return;const p=demoProducts[Math.floor(Math.random()*demoProducts.length)];orders.unshift({id:nextId++,table:'Mesa '+String(Math.ceil(Math.random()*10)).padStart(2,'0'),items:['1 × '+p.name],total:p.price,status:'pending',time:new Date().toLocaleTimeString('es-PA',{hour:'2-digit',minute:'2-digit'})});render();notify('Nuevo pedido de ejemplo creado')});document.getElementById('addReservation').addEventListener('click',()=>{if(!demo)return;reservations.unshift({id:Math.max(...reservations.map(x=>x.id),0)+1,time:'20:30',name:'Reserva de ejemplo',party:2,table:'Mesa 03',state:'Pendiente'});render();notify('Reserva de ejemplo agregada')});
render();const initial=location.hash.slice(1);if(['inicio','pedidos','cocina','reservas','menu','gerencia'].includes(initial))show(initial);

/* Advanced interactive demo workspace. All mutations remain in browser memory. */
const originalShow=show;
show=function(page){if(!demo&&['salon','caja','inventario','clientes','personal','incidencias','simulador'].includes(page)){notify('Activa la demostración para explorar este módulo');return}originalShow(page);renderAdvanced()};
const stockSeed=[{name:'Harina de trigo',unit:'kg',qty:18,min:8,cost:2.2},{name:'Queso mozzarella',unit:'kg',qty:3,min:5,cost:9.5},{name:'Tomate fresco',unit:'kg',qty:7,min:5,cost:3.4},{name:'Carne de res',unit:'kg',qty:6,min:4,cost:12.5},{name:'Aceite de oliva',unit:'L',qty:1.5,min:3,cost:10},{name:'Limón',unit:'kg',qty:4,min:3,cost:3.1},{name:'Lechuga',unit:'kg',qty:2,min:4,cost:4.3}];
let tables=[],stock=[],incidents=[],selectedTable=null,selectedBill=null,checks=[],demoWasActive=false;
const clients=[{name:'María González',visits:14,points:420,preference:'Mesa junto a la ventana',consent:true},{name:'Carlos Pérez',visits:8,points:210,preference:'Sin preferencias registradas',consent:false},{name:'Familia Rodríguez',visits:19,points:620,preference:'Alerta alimentaria registrada',consent:true}];
const staff=[{name:'Andrea López',role:'Recepción',shift:'12:00 – 20:00',station:'Salón'},{name:'Luis Moreno',role:'Mesero',shift:'11:00 – 19:00',station:'Mesas 01–06'},{name:'Sofía Ramos',role:'Chef',shift:'12:00 – 22:00',station:'Cocina caliente'},{name:'Mateo Díaz',role:'Cajero',shift:'14:00 – 22:00',station:'Caja 01'}];
function seedAdvanced(){tables=Array.from({length:12},(_,i)=>({id:i+1,capacity:i%4===0?6:i%3===0?2:4,status:'free',guest:null,orderIds:[],started:null}));tables[1].status='occupied';tables[1].guest='María González';tables[3].status='kitchen';tables[3].orderIds=[1048];tables[7].status='bill';tables[7].orderIds=[1047];stock=stockSeed.map(x=>({...x}));incidents=[{id:1,title:'Mozzarella bajo mínimo',severity:'Alta',owner:'Cocina',done:false},{id:2,title:'Revisar tiempos de mesa 04',severity:'Media',owner:'Salón',done:false}];checks=[];selectedTable=null;selectedBill=null}
function renderAdvanced(){if(!demo)return;if(!demoWasActive){seedAdvanced();demoWasActive=true}renderRoom();renderBills();renderStock();renderClients();renderStaff();renderIncidents();renderSim()}
function renderRoom(){document.getElementById('roomGrid').innerHTML=tables.map(t=>'<button class="table-unit '+(t.status==='occupied'?'occupied':t.status==='kitchen'?'kitchen':t.status==='bill'?'bill':'')+'" data-table="'+t.id+'"><strong>'+String(t.id).padStart(2,'0')+'</strong><small>'+({free:'Libre',occupied:'Ocupada',kitchen:'En cocina',bill:'Cuenta'}[t.status])+'</small><small>♙ '+t.capacity+'</small></button>').join('');renderTableDetail()}
function renderTableDetail(){const t=tables.find(x=>x.id===selectedTable);document.getElementById('tableDetail').innerHTML=!t?'<h2>Selecciona una mesa</h2><p>Consulta su estado, asigna clientes, registra un pedido y pasa a caja.</p>':'<span class="eyebrow">MESA '+String(t.id).padStart(2,'0')+'</span><h2 style="margin-top:12px">'+({free:'Disponible',occupied:'En servicio',kitchen:'Pedido en cocina',bill:'Cuenta pendiente'}[t.status])+'</h2><p>Capacidad '+t.capacity+' personas</p><div class="detail-line"><span>Cliente</span><b>'+safe(t.guest||'Sin asignar')+'</b></div><div class="detail-line"><span>Pedidos vinculados</span><b>'+t.orderIds.length+'</b></div><div class="detail-line"><span>Importe acumulado</span><b>'+money(orders.filter(o=>t.orderIds.includes(o.id)).reduce((s,o)=>s+o.total,0))+'</b></div><div class="detail-actions">'+(t.status==='free'?'<button class="btn" data-seat="'+t.id+'">+ Ocupar mesa</button>':'<button class="btn" data-table-order="'+t.id+'">+ Añadir pedido</button><button class="btn alt" data-table-bill="'+t.id+'">Ir a caja →</button>')+'</div>'}
function renderBills(){const active=tables.filter(t=>t.status!=='free');document.getElementById('openBills').innerHTML=active.length?active.map(t=>'<div class="detail-line"><div><b>Mesa '+String(t.id).padStart(2,'0')+'</b><p>'+t.orderIds.length+' pedido(s)</p></div><div><b>'+money(orders.filter(o=>t.orderIds.includes(o.id)).reduce((s,o)=>s+o.total,0))+'</b> <button class="btn alt" data-select-bill="'+t.id+'">Cobrar</button></div></div>').join(''):noData('No hay cuentas abiertas');const t=tables.find(x=>x.id===selectedBill);const subtotal=t?orders.filter(o=>t.orderIds.includes(o.id)).reduce((s,o)=>s+o.total,0):0;document.getElementById('checkoutPanel').innerHTML=t?'<h3>Mesa '+String(t.id).padStart(2,'0')+'</h3><div class="detail-line"><span>Subtotal</span><b>'+money(subtotal)+'</b></div><div class="field"><label for="splitCount">Dividir entre personas</label><input id="splitCount" type="number" min="1" max="12" value="1"></div><div class="field"><label for="tipPct">Propina (%)</label><input id="tipPct" type="number" min="0" max="100" value="10"></div><div class="field"><label for="discountPct">Descuento (%)</label><input id="discountPct" type="number" min="0" max="100" value="0"></div><div class="field"><label for="paymentMethod">Método de pago</label><select id="paymentMethod"><option>Efectivo</option><option>Tarjeta</option><option>Pago mixto (simulado)</option></select></div><div id="checkoutTotal"></div><button class="btn terra" id="completePayment">Confirmar cobro simulado</button>':noData('Selecciona una cuenta para calcular el cobro');if(t)calcBill()}
function calcBill(){const t=tables.find(x=>x.id===selectedBill);if(!t)return;const subtotal=orders.filter(o=>t.orderIds.includes(o.id)).reduce((s,o)=>s+o.total,0);const split=Math.max(1,Number(document.getElementById('splitCount')?.value||1));const tip=Math.min(100,Math.max(0,Number(document.getElementById('tipPct')?.value||0)));const discount=Math.min(100,Math.max(0,Number(document.getElementById('discountPct')?.value||0)));const total=subtotal*(1-discount/100)*(1+tip/100);document.getElementById('checkoutTotal').innerHTML='<div class="detail-line"><span>Total estimado</span><strong>'+money(total)+'</strong></div><div class="detail-line"><span>Por persona</span><strong>'+money(total/split)+'</strong></div><p class="muted">Impuestos no incluidos: deben configurarse conforme a la normativa aplicable.</p>'}
function renderStock(){const low=stock.filter(x=>x.qty<x.min);document.getElementById('stockStats').innerHTML=metric('Ingredientes',stock.length,'Registrados en demo')+metric('Bajo mínimo',low.length,'Requieren atención')+metric('Valor estimado',money(stock.reduce((s,x)=>s+x.qty*x.cost,0)),'Costo del stock')+metric('Platos afectados',low.length?'Por revisar':'0','Dependencias de receta');document.getElementById('stockTable').innerHTML='<table><thead><tr><th>Ingrediente</th><th>Existencia</th><th>Mínimo</th><th>Costo unitario</th><th>Estado</th><th>Ajustar</th></tr></thead><tbody>'+stock.map((x,i)=>'<tr><td><b>'+safe(x.name)+'</b></td><td>'+x.qty+' '+safe(x.unit)+'</td><td>'+x.min+' '+safe(x.unit)+'</td><td>'+money(x.cost)+'</td><td><span class="pill '+(x.qty<x.min?'':'ready')+'">'+(x.qty<x.min?'Reponer':'Disponible')+'</span></td><td><button class="btn alt" data-stock="'+i+'">+ Recibir</button></td></tr>').join('')+'</tbody></table>';document.getElementById('purchaseProposal').innerHTML='<h2>Recomendación de compra</h2><p>Basada en mínimos de inventario de ejemplo, no en una previsión automática.</p>'+(low.length?low.map(x=>'<div class="detail-line"><span>'+safe(x.name)+'</span><b>'+Math.ceil(x.min*1.5-x.qty)+' '+safe(x.unit)+' · '+money(Math.ceil(x.min*1.5-x.qty)*x.cost)+'</b></div>').join(''):noData('No hay ingredientes por debajo del mínimo.'))}
function renderClients(){document.getElementById('customerProfiles').innerHTML=clients.map(c=>'<article class="profile"><div class="face">♙</div><strong>'+safe(c.name)+'</strong><p>'+c.visits+' visitas · '+c.points+' puntos</p><div class="detail-line"><span>Preferencia</span><b>'+safe(c.consent?c.preference:'Sin consentimiento')+'</b></div><span class="pill ready">'+(c.consent?'Consentimiento registrado (demo)':'No autorizado')+'</span></article>').join('')}
function renderStaff(){document.getElementById('staffProfiles').innerHTML=staff.map((x,i)=>'<article class="profile"><div class="face">'+['👩‍💼','🧑‍🍳','👩‍🍳','👨‍💼'][i]+'</div><strong>'+safe(x.name)+'</strong><p>'+safe(x.role)+'</p><div class="detail-line"><span>Turno</span><b>'+safe(x.shift)+'</b></div><div class="detail-line"><span>Estación</span><b>'+safe(x.station)+'</b></div><span class="pill ready">Turno programado</span></article>').join('')}
function renderIncidents(){document.getElementById('incidentList').innerHTML='<div class="panel-head"><h2>Incidencias registradas</h2><span class="pill">'+incidents.filter(x=>!x.done).length+' abiertas</span></div>'+incidents.map(x=>'<div class="alert-row"><div class="detail-line"><div><b>'+safe(x.title)+'</b><p>Prioridad '+safe(x.severity)+' · Responsable: '+safe(x.owner)+'</p></div><button class="btn alt" data-resolve="'+x.id+'" '+(x.done?'disabled':'')+'>'+(x.done?'Resuelta':'Resolver')+'</button></div></div>').join('')}
function renderSim(){const price=Math.max(0,Number(document.getElementById('simPrice').value||0)),cost=Math.max(0,Number(document.getElementById('simCost').value||0)),volume=Math.max(0,Number(document.getElementById('simVolume').value||0)),discount=Number(document.getElementById('simDiscount').value||0);document.getElementById('discountLabel').textContent=discount+'%';const net=price*(1-discount/100),margin=net-cost;document.getElementById('simResults').innerHTML=metric('Precio efectivo',money(net),'Tras descuento')+metric('Margen unitario',money(margin),'Antes de gastos fijos')+metric('Contribución semanal',money(margin*volume),'Volumen constante supuesto')+'<div class="notice">Escenario hipotético. No considera elasticidad de demanda, impuestos, mano de obra ni costos indirectos.</div>'}
document.addEventListener('click',e=>{if(!demo)return;const button=e.target.closest('button');if(!button)return;const d=button.dataset;
if(d.table){selectedTable=Number(d.table);renderTableDetail()}
if(d.seat){const t=tables.find(x=>x.id===Number(d.seat));t.status='occupied';t.guest='Cliente de ejemplo';t.started=Date.now();renderAdvanced();notify('Mesa '+t.id+' ocupada')}
if(d.tableOrder){const t=tables.find(x=>x.id===Number(d.tableOrder));const p=demoProducts[Math.floor(Math.random()*demoProducts.length)];const id=nextId++;orders.unshift({id,table:'Mesa '+String(t.id).padStart(2,'0'),items:['1 × '+p.name],total:p.price,status:'pending',time:new Date().toLocaleTimeString('es-PA',{hour:'2-digit',minute:'2-digit'})});t.orderIds.push(id);t.status='kitchen';render();notify('Comanda enviada a cocina')}
if(d.tableBill){selectedBill=Number(d.tableBill);const t=tables.find(x=>x.id===selectedBill);t.status='bill';renderAdvanced();show('caja')}
if(d.selectBill){selectedBill=Number(d.selectBill);renderBills()}
if(d.stock!==undefined){const x=stock[Number(d.stock)];x.qty+=Math.max(1,Math.ceil(x.min*.5));renderStock();notify('Entrada de inventario simulada')}
if(d.resolve){const x=incidents.find(x=>x.id===Number(d.resolve));if(x)x.done=true;renderIncidents();notify('Incidencia resuelta')}
});
document.getElementById('checkoutPanel').addEventListener('input',calcBill);
document.getElementById('checkoutPanel').addEventListener('click',e=>{if(e.target.id!=='completePayment'||!demo)return;const t=tables.find(x=>x.id===selectedBill);if(!t)return;checks.push({table:t.id,at:new Date().toISOString()});t.orderIds.forEach(id=>{const o=orders.find(x=>x.id===id);if(o)o.status='delivered'});t.status='free';t.guest=null;t.orderIds=[];selectedBill=null;render();renderAdvanced();notify('Cobro registrado en la simulación; mesa liberada')});
document.getElementById('resetTables').addEventListener('click',()=>{if(!demo)return;seedAdvanced();renderAdvanced();notify('Salón de demostración reiniciado')});
document.getElementById('restockAll').addEventListener('click',()=>{if(!demo)return;renderStock();document.getElementById('purchaseProposal').scrollIntoView({behavior:'smooth'});notify('Propuesta calculada con los mínimos configurados')});
document.getElementById('newIncident').addEventListener('click',()=>{if(!demo)return;incidents.unshift({id:Math.max(0,...incidents.map(x=>x.id))+1,title:'Incidencia de ejemplo',severity:'Media',owner:'Gerencia',done:false});renderIncidents();notify('Incidencia registrada en demo')});
['simPrice','simCost','simVolume','simDiscount'].forEach(id=>document.getElementById(id).addEventListener('input',renderSim));
document.getElementById('demoToggle').addEventListener('click',()=>{if(!demo){demoWasActive=false;if(['salon','caja','inventario','clientes','personal','incidencias','simulador'].includes(location.hash.slice(1)))originalShow('inicio')}else{demoWasActive=false;renderAdvanced()}});
/* Ensure first demo toggle initializes all advanced modules after the original listener. */
document.getElementById('demoToggle').addEventListener('click',()=>{if(demo){demoWasActive=false;renderAdvanced()}else if(['salon','caja','inventario','clientes','personal','incidencias','simulador'].includes(location.hash.slice(1)))originalShow('inicio')});
</script></body></html>